{"code": "import zipfile
import pandas as pd

# Try to open the zip file
try:
    with zipfile.ZipFile('data/train.csv.zip', 'r') as z:
        print("train.csv.zip contents:")
        print(z.namelist())
except zipfile.BadZipFile as e:
    print(f"train.csv.zip is not a valid zip file: {e}")

# Try reading as a regular CSV
try:
    df = pd.read_csv('data/train.csv.zip', nrows=5)
    print("\nSuccessfully read as CSV:")
    print(df.head())
except Exception as e:
    print(f"\nCannot read as CSV: {e}")"}

